package materiewelle.course.content

import materiewelle.core.course.StationId

/** Disclosure is content metadata, independent of station number or array position. */
enum class ContentVisibility { ALWAYS, AFTER_ANSWER, AFTER_TRANSFER, AFTER_REFERENCE }

/** Text and evidence stay readable without playing an animation or taking a quiz. */
data class ExplanationStep(
    val title: String,
    val text: String,
    val visibility: ContentVisibility = ContentVisibility.ALWAYS,
)

enum class SourceCategory { LITERATURE, WORKING_MATERIAL }

data class ContentSource(
    val id: String,
    val location: String,
    val status: String,
    val url: String? = null,
    val category: SourceCategory = SourceCategory.LITERATURE,
    val title: String = id,
)

data class StationContent(
    val id: StationId,
    val title: String,
    val question: String,
    val introduction: String,
    val steps: List<ExplanationStep>,
    val formulas: List<String>,
    val known: String,
    val open: String,
    val newInsight: String,
    val year: String,
    val history: String,
    val sources: List<ContentSource>,
    val limits: List<String>,
    val hints: List<String>,
    val action: String,
    val transfer: String,
    val answerFormulas: List<String> = emptyList(),
    val referenceFormulas: List<String> = emptyList(),
    val transferFormulas: List<String> = emptyList(),
)

