        StationContent(
            StationId.S10_GEOMETRY,
            "Woher kommt die Winkelbedingung?",
            "Welche Zusatzwege müssen für konstruktive Überlagerung zusammenpassen?",
            "Ein Gangunterschied vergleicht die Wege zweier Beiträge bis zu einer gemeinsamen Wellenfront. Entscheide in der aktiven Zeichnung zuerst über Bezugslinien und Zusatzwege. Danach vergleichen wir zwei Geometrien: Bragg an Netzebenen und das ausgewählte DG-Oberflächenmodell.",
            listOf(
                ExplanationStep("A1 · Bragg-Bezugslinien", "Zeichne zwei parallele Netzebenen mit senkrechtem Abstand d. Der einfallende und der ausfallende Strahl bilden den Winkel θB jeweils mit der Ebene. θB ist damit nicht zur Normalen und nicht zu einem beliebigen Detektorarm definiert."),
                ExplanationStep("A2 · Zwei Zusatzstrecken", "Vergleiche Beiträge aus benachbarten Ebenen über passende senkrechte Hilfslinien. Der Weg zur tieferen Ebene hat auf der Einfallsseite die Zusatzstrecke d sin θB. Auf der Ausfallsseite kommt eine zweite Strecke d sin θB hinzu. Zusammen ist der Gangunterschied Δs = 2d sin θB."),
                ExplanationStep("A3 · Phasenpassung", "Wenn der Gangunterschied ein ganzzahliges Vielfaches der Wellenlänge ist, passen die Beiträge in dieser idealisierten Konstruktion konstruktiv zusammen: 2d sin θB = nλ. n bezeichnet die Beugungsordnung."),
                ExplanationStep("B · Getrennte DG-Oberflächenzeichnung", "Nun betrachten wir normal einfallende Beiträge an den ausgewählten Ni(111)-Oberflächenreihen. D ist deren Abstand in der betrachteten Richtung. φ wird von der äußeren Oberflächennormalen gemessen. Die einfallenden Beiträge haben bei Normalinzidenz keinen entsprechenden Reihen-Versatz im Ankunftsweg; für die Ausfallsrichtung entsteht Δs = D sin φ. Daher nλ = D sin φ."),
                ExplanationStep("Keine universelle Winkelumrechnung", "Beide Zeichnungen verwenden Phasenpassung, aber nicht dieselbe Geometrie. d ≠ D und θB ist nicht automatisch φ/2. Jede Umrechnung muss aus den Linien der konkreten Zeichnung folgen."),
