    init {
        require(stations.map { it.id }.toSet() == StationId.entries.toSet())
        require(stations.size == StationId.entries.size)
        require(stations.all { it.steps.isNotEmpty() && it.sources.isNotEmpty() && it.hints.size >= 2 })
    }

    operator fun get(id: StationId): StationContent = stations.single { it.id == id }
}
